fn source_constructor_capacity<F1, F2, F3, D>(grant: RetainedCloneGrant, additional_birth: usize) -> Result<usize, DocumentStoreOwnersAdmissionError<P, Mutation>>
where F1: semio_framework_value::FactoryPayloadRetirement, F2: semio_framework_value::FactoryPayloadRetirement, F3: semio_framework_value::FactoryPayloadRetirement,
{
    let capacity = Self::source_birth_bytes::<F1, F2, F3, D>().and_then(|capacity| capacity.checked_add(additional_birth).ok_or_else(|| ValueError::literal(semio_framework_value::ValueRefusalKind::OwnershipLimit, "catalog original source tree extent overflow"))).map_err(|error| DocumentStoreOwnersAdmissionError { error, owners: None, progress: Default::default() })?;
    let refusal = if grant.maximum_items == 0 { Some((semio_framework_value::ValueRefusalKind::WorkLimit, "catalog source constructor requires one admitted item")) }
        else if grant.maximum_depth == 0 { Some((semio_framework_value::ValueRefusalKind::DepthLimit, "catalog source constructor requires original owner depth")) }
        else if grant.maximum_capacity_bytes < capacity { Some((semio_framework_value::ValueRefusalKind::OwnershipLimit, "catalog source constructor exceeds supplied capacity")) }
        else { None };
    if let Some((kind, message)) = refusal { return Err(DocumentStoreOwnersAdmissionError { error: ValueError::literal(kind, message), owners: None, progress: Default::default() }); }
    Ok(capacity)
}
